{
  "arguments": [
    {
      "claim": "The Republic of Calvaro breached its obligation not to use cluster munitions under Article 1(a) of the Convention on Cluster Munitions by authorising, through the co‑director’s signature, the deployment of cluster munitions against the Drennick armoured column.",
      "reasoning": "Article 1(a) obliges a State Party never to use cluster munitions. The Convention’s prohibition is absolute and does not require the physical launch of the weapon by the State’s own forces; any act that results in the deployment of cluster munitions by forces acting under the State’s authority is covered. By signing the tasking order, the Calvaran co‑director exercised the legal authority of the State to approve the strike, thereby causing the use of cluster munitions. Consequently, Calvaro’s conduct satisfies the factual element of ‘use’ and violates Article 1(a).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccm",
          "article": "1(1)(a)",
          "quoted_text": "Use cluster munitions;"
        }
      ]
    },
    {
      "claim": "The Republic of Calvaro also violated Article 1(c) of the Convention by providing assistance that encouraged and induced the non‑party Sorvenia to employ cluster munitions.",
      "reasoning": "Article 1(c) prohibits a State Party from \"Assist, encourage or induce anyone to engage in any activity prohibited to a State Party under this Convention.\" The definition of assistance in Article 4(1)(e)(b) expressly includes the provision of information on the types, quantities and precise locations of cluster munition strikes. By co‑signing the tasking order, the Calvaran co‑director not only approved the munition but also supplied the targeting data required for the strike, thereby furnishing the very information contemplated by Article 4(1)(e)(b). This conduct constitutes assistance that encouraged and induced Sorvenia’s use of cluster munitions, breaching Article 1(c).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccm",
          "article": "1",
          "quoted_text": "Assist, encourage or induce anyone to engage in any activity prohibited to a State Party under this Convention."
        },
        {
          "type": "treaty",
          "instrument": "ccm",
          "article": "4(1)(e)(b)",
          "quoted_text": "Such assistance shall include, where available, information on types and quantities of the cluster munitions used, precise locations of cluster munition strikes and areas in which cluster munition remnants are known to be located."
        }
      ]
    },
    {
      "claim": "The fact that the actual delivery of the munitions was carried out by Sorvenian aircraft does not excuse Calvaro, because the Convention’s prohibitions on use and assistance apply irrespective of the nationality of the personnel executing the strike.",
      "reasoning": "The Convention imposes obligations on State Parties to refrain from using cluster munitions and from assisting others in their use, without limiting those duties to actions performed by the State’s own armed forces. The purpose of the treaty is to prevent the deployment of cluster munitions altogether, and the assistance prohibition is expressly worded to cover any entity, including non‑parties, that a State Party helps. Therefore, Calvaro’s participation in the decision‑making process and its provision of targeting information constitute a breach even though Sorvenian pilots physically released the weapons.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccm",
          "article": "1",
          "quoted_text": "Assist, encourage or induce anyone to engage in any activity prohibited to a State Party under this Convention."
        },
        {
          "type": "treaty",
          "instrument": "ccm",
          "article": "1(1)(a)",
          "quoted_text": "Use cluster munitions;"
        }
      ]
    }
  ]
}
